// Audit captures this operation's existing stored changes without getters, mutators or additional database work.
// Updates, soft deletes and restorations record assigned or changed fields plus the key; create and delete record every field.
// Standalone Compare results have no captured operation and cannot become lifecycle audit records.
func (changes EntryChanges) Audit(policy EntryAuditPolicy) (record.Model[Entry, model.ID[Entry]], error) {
	operation, present := changes.operation.Get()
	if !present {
		return record.Model[Entry, model.ID[Entry]]{}, foundryfault.New(foundryfault.Missing, "audit requires captured model changes")
	}
	item, present := changes.after.Get()
	if !present {
		item, present = changes.before.Get()
	}
	if !present {
		return record.Model[Entry, model.ID[Entry]]{}, foundryfault.New(foundryfault.Missing, "audit requires a stored model snapshot")
	}
	builder, err := record.NewBuilder(item.FoundryReference(), operation, "id", policy.ID)
	if err != nil {
		return record.Model[Entry, model.ID[Entry]]{}, err
	}
	if err = record.Capture(builder, "id", codec.ID[Entry](), changes.fields.ID, policy.ID); err != nil {
		return record.Model[Entry, model.ID[Entry]]{}, err
	}
	if err = record.Capture(builder, "sequence", codec.Signed[int64](), changes.fields.Sequence, policy.Sequence); err != nil {
		return record.Model[Entry, model.ID[Entry]]{}, err
	}
	if err = record.Capture(builder, "area", codec.String[string](), changes.fields.Area, policy.Area); err != nil {
		return record.Model[Entry, model.ID[Entry]]{}, err
	}
	if err = record.Capture(builder, "operation", codec.Unsigned[lifecycle.Operation](), changes.fields.Operation, policy.Operation); err != nil {
		return record.Model[Entry, model.ID[Entry]]{}, err
	}
	if err = record.Capture(builder, "action", codec.String[string](), changes.fields.Action, policy.Action); err != nil {
		return record.Model[Entry, model.ID[Entry]]{}, err
	}
	if err = record.Capture(builder, "version", codec.Unsigned[uint32](), changes.fields.Version, policy.Version); err != nil {
		return record.Model[Entry, model.ID[Entry]]{}, err
	}
	if err = record.Capture(builder, "subject", codec.Nullable(codec.JSON[model.Identity]()), changes.fields.Subject, policy.Subject); err != nil {
		return record.Model[Entry, model.ID[Entry]]{}, err
	}
	if err = record.Capture(builder, "subject_key", codec.Nullable(codec.String[string]()), changes.fields.SubjectKey, policy.SubjectKey); err != nil {
		return record.Model[Entry, model.ID[Entry]]{}, err
	}
	if err = record.Capture(builder, "payload", codec.JSON[json.RawMessage](), changes.fields.Payload, policy.Payload); err != nil {
		return record.Model[Entry, model.ID[Entry]]{}, err
	}
	if err = record.Capture(builder, "redacted", codec.Bool[bool](), changes.fields.Redacted, policy.Redacted); err != nil {
		return record.Model[Entry, model.ID[Entry]]{}, err
	}
	if err = record.Capture(builder, "redaction", codec.Unsigned[uint8](), changes.fields.Redaction, policy.Redaction); err != nil {
		return record.Model[Entry, model.ID[Entry]]{}, err
	}
	if err = record.Capture(builder, "origin", codec.JSON[attribution.Origin](), changes.fields.Origin, policy.Origin); err != nil {
		return record.Model[Entry, model.ID[Entry]]{}, err
	}
	if err = record.Capture(builder, "actor_key", codec.Nullable(codec.String[string]()), changes.fields.ActorKey, policy.ActorKey); err != nil {
		return record.Model[Entry, model.ID[Entry]]{}, err
	}
	if err = record.Capture(builder, "correlation", codec.Nullable(codec.String[string]()), changes.fields.Correlation, policy.Correlation); err != nil {
		return record.Model[Entry, model.ID[Entry]]{}, err
	}
	if err = record.Capture(builder, "request_method", codec.String[string](), changes.fields.RequestMethod, policy.RequestMethod); err != nil {
		return record.Model[Entry, model.ID[Entry]]{}, err
	}
	if err = record.Capture(builder, "request_route", codec.String[string](), changes.fields.RequestRoute, policy.RequestRoute); err != nil {
		return record.Model[Entry, model.ID[Entry]]{}, err
	}
	if err = record.Capture(builder, "created_at", codec.DateTime(), changes.fields.CreatedAt, policy.CreatedAt); err != nil {
		return record.Model[Entry, model.ID[Entry]]{}, err
	}
	return builder.Build()
}

